                    ? partitionState.position.currentLeader.epoch
                    : partitionState.position.offsetEpoch;
            }
            
            allConsumed.put(topicPartition, new OffsetAndMetadata(
                partitionState.position.offset,
                epochToCommit,
                ""));
        }
    });
    return allConsumed;
} 
