public synchronized Map<TopicPartition, OffsetAndMetadata> allConsumed(ConsumerMetadata metadata) {
    Map<TopicPartition, OffsetAndMetadata> allConsumed = new HashMap<>();
    assignment.forEach((topicPartition, partitionState) -> {
        if (partitionState.hasValidPosition()) {
            // Fetch the latest leader epoch from metadata at commit time
            Metadata.LeaderAndEpoch latestLeader = metadata.currentLeader(topicPartition);
            Optional<Integer> epochToCommit = latestLeader.epoch.isPresent() 
                ? latestLeader.epoch 
                : partitionState.position.offsetEpoch;  // Fallback to offsetEpoch
            
            allConsumed.put(topicPartition, new OffsetAndMetadata(
                partitionState.position.offset,
                epochToCommit,
                ""));
        }
    });
    return allConsumed;
} 
