            .setSubtopologyId("s1")
            .setSourceTopics(List.of("in"))
            .setStateChangelogTopics(List.of(new TopicInfo().setName("store-changelog")))));
        CoordinatorMetadataImage image = new MetadataImageBuilder()
            .addTopic(Uuid.randomUuid(), "in", 1)
            .addTopic(Uuid.randomUuid(), "store-changelog", 1)
            .buildCoordinatorMetadataImage();

        // A static member ran stateful task s1_0 on process A and left with epoch -2. Warm-up tasks are enabled, the
        // default.
        MockTaskAssignor assignor = new MockTaskAssignor("sticky");
        assignor.prepareGroupAssignment(Map.of("member-new", mkTasksTuple(TaskRole.ACTIVE, mkTasks("s1", 0))));
        GroupMetadataManagerTestContext context = new GroupMetadataManagerTestContext.Builder()
            .withStreamsGroupTaskAssignors(List.of(assignor))
            .withStreamsGroupAssignmentRefiner(new AssignmentRefinerImpl())
            .withMetadataImage(image)
            .withStreamsGroup(new StreamsGroupBuilder("app", 10)
                .withMember(streamsGroupMemberBuilderWithDefaults("member-old", "instance-1")
                    .setMemberEpoch(LEAVE_GROUP_STATIC_MEMBER_EPOCH)
                    .setPreviousMemberEpoch(10)
                    .setProcessId("process-A")
                    .setAssignedTasks(mkTasksTupleWithCommonEpoch(TaskRole.ACTIVE, 10, mkTasks("s1", 0)))
                    .build())
                .withTargetAssignment("member-old", mkTasksTuple(TaskRole.ACTIVE, mkTasks("s1", 0)))
                .withTargetAssignmentEpoch(10)
                .withTopology(StreamsTopology.fromHeartbeatRequest(topology))
                .withValidatedTopologyEpoch(0)
                .withMetadataHash(computeGroupHash(Map.of(
                    "in", computeTopicHash("in", image),
                    "store-changelog", computeTopicHash("store-changelog", image))))
                .withLastAssignmentConfigs(AssignmentConfigsImpl.DEFAULT))
            .build();

        // It rejoins under a new member ID from process B. The process change bumps the group epoch, so the target
        // assignment is computed and refined in this heartbeat.
        CoordinatorResult<StreamsGroupHeartbeatResult, CoordinatorRecord> result = context.streamsGroupHeartbeat(
            new StreamsGroupHeartbeatRequestData()
                .setGroupId("app")
                .setMemberId("member-new")
                .setMemberEpoch(JOIN_GROUP_MEMBER_EPOCH)
                .setInstanceId("instance-1")
                .setProcessId("process-B")
                .setRebalanceTimeoutMs(1500)
                .setTopology(topology)
                .setActiveTasks(List.of())
                .setStandbyTasks(List.of())
                .setWarmupTasks(List.of()));

