public class GlobalStoreHeadersRepro {

    static final List<String> SEEN = new ArrayList<>();

    static final class RecordingDeserializer implements Deserializer<String> {
        @Override
        public String deserialize(String topic, byte[] data) {
            SEEN.add("called without headers");
            return data == null ? null : new String(data, StandardCharsets.UTF_8);
        }

        @Override
        public String deserialize(String topic, Headers headers, byte[] data) {
            var origin = headers == null ? null : headers.lastHeader("origin");
            SEEN.add(origin == null ? "empty headers" : "origin=" + new String(origin.value(), StandardCharsets.UTF_8));
            return data == null ? null : new String(data, StandardCharsets.UTF_8);
        }
    }

    static Serde<String> recordingSerde() {
        return Serdes.serdeFrom(new StringSerializer(), new RecordingDeserializer());
    }

    static RecordHeaders origin(String value) {
        var headers = new RecordHeaders();
        headers.add("origin", value.getBytes(StandardCharsets.UTF_8));
        return headers;
    }

