                "global-processor", () -> new Processor<String, String, Void, Void>() {
                    private KeyValueStore<String, String> store;

                    @Override
                    public void init(ProcessorContext<Void, Void> context) {
                        store = context.getStateStore("global-store");
                    }

                    @Override
                    public void process(Record<String, String> record) {
                        store.put(record.key(), record.value());
                    }
                });
        topology.addSource("stream-source", new StringDeserializer(), new StringDeserializer(), "stream-topic");
        topology.addProcessor("reader", () -> new Processor<String, String, Void, Void>() {
            private KeyValueStore<String, String> globalStore;
            private KeyValueStore<String, String> taskStore;

            @Override
            public void init(ProcessorContext<Void, Void> context) {
                globalStore = context.getStateStore("global-store");
                taskStore = context.getStateStore("task-store");
            }

            @Override
            public void process(Record<String, String> record) {
                taskStore.put("k", "task-value");
                SEEN.clear();
                taskStore.get("k");
                System.out.println("stream thread, task store read: " + SEEN);
                SEEN.clear();
                globalStore.get("k");
                System.out.println("stream thread, global store read: " + SEEN);
            }
        }, "stream-source");
        topology.addStateStore(
                Stores.keyValueStoreBuilder(Stores.inMemoryKeyValueStore("task-store"), Serdes.String(),
                        recordingSerde()).withLoggingDisabled(),
